def audit(events, at):
    selected = {}
    for event in events:
        if event['seen'] > at:
            continue
        sides = selected.setdefault(event['key'], {})
        side = event['side']
        epoch = event['epoch']
        digest = event['digest']
        old = sides.get(side)
        if old is None or epoch > old[0]:
            sides[side] = (epoch, {digest})
        elif epoch == old[0]:
            old[1].add(digest)
    result = {}
    for key, sides in selected.items():
        if any(len(value[1]) > 1 for value in sides.values()):
            result[key] = 'conflict'
        elif 'L' not in sides or 'R' not in sides:
            result[key] = 'pending'
        elif sides['L'][0] != sides['R'][0]:
            result[key] = 'pending'
        elif sides['L'][1] != sides['R'][1]:
            result[key] = 'diverged'
        else:
            result[key] = 'verified'
    return result

